    pts = [(r, c) for r in range(h) for c in range(w) if out[r][c] == 1]
    if len(pts) >= 2:
        # Find two trail cells that establish the step direction.
        direction = None
        for i, (r1, c1) in enumerate(pts):
            for r2, c2 in pts[i + 1:]:
                dr, dc = r2 - r1, c2 - c1
                if abs(dr) == abs(dc) and dr != 0:
                    direction = (1 if dr > 0 else -1, 1 if dc > 0 else -1)
                    break
            if direction:
                break
        if direction:
            dr, dc = direction
            # Start at the furthest existing point along this diagonal, then extend to the edge.
            r, c = max(pts, key=lambda p: p[0] * dr + p[1] * dc)
            r += dr
            c += dc
            while 0 <= r < h and 0 <= c < w:
                if out[r][c] == grid[0][0]:
                    out[r][c] = 1
                r += dr
                c += dc
